    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*80, 200+Math.sin(t*0.75+4)*60, 0.085, 1.8]
